import { readFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";

const generated = new URL("../src/generated/schema.d.ts", import.meta.url);
const source = new URL("../openapi/motifuse.openapi.json", import.meta.url);
const banner = `/**
 * This file was auto-generated by openapi-typescript.
 * Do not make direct changes to the file.
 */

`;
const actual =
  banner + astToString(await openapiTS(source, { alphabetize: true, defaultNonNullable: false }));

const expected = await readFile(generated, "utf8");
if (expected !== actual) {
  console.error("Generated OpenAPI declarations are stale. Run npm run openapi:generate.");
  process.exitCode = 1;
} else {
  console.log("Generated OpenAPI declarations match the committed contract.");
}
